  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Propagates water flow from the SOURCE outward up to a specified distance using BFS.
   * Algorithm: 
   *   1. Record current filled tile count.
   *   2. Initialize BFS queue with sourceCell.coord and a visited set.
   *   3. Iterate step from 1 to distance:
   *      a. For each coordinate in the current frontier:
   *         i. Get the corresponding cell.
   *         ii. If cell has connections, iterate through its connection directions.
   *         iii. For each direction, compute neighbor coordinate using offset.
   *         iv. If neighbor is within bounds, is a valid cell, and unvisited:
   *             - Check if neighbor connects back (neighbor's connections include opposite direction).
   *             - If matched, mark neighbor as filled, add to filledTiles, enqueue, mark visited.
   *      b. Advance to next step.
   *   4. Calculate newly filled tiles: newCount = filledTiles.size() - recordedCount.
   *   5. Update prevFilledTiles = newCount.
   * Related Features: filledTiles, prevFilledTiles, sourceCell, cell (2D array)
   * Related Classes: Coordinate, Direction, Pipe
   * Input: distance : int - Maximum BFS expansion steps. Range: >= 0.
   * Output: void
   * Pre-condition: Source cell exists and has been marked filled via fillBeginTile().
   * Post-condition: All reachable pipes within distance units from the source are marked as filled. filledTiles is updated with new coordinates. prevFilledTiles reflects the count of tiles filled in this round.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    int recordedCount = filledTiles.size();
    Queue<Coordinate> queue = new ArrayDeque<>();
    Set<Coordinate> visited = new HashSet<>();
    queue.add(sourceCell.getCoord());
    visited.add(sourceCell.getCoord());

    int[] dRow = {-1, 1, 0, 0};
    int[] dCol = {0, 0, 1, -1};

    for (int step = 1; step <= distance; step++) {
      int size = queue.size();
      for (int i = 0; i < size; i++) {
        Coordinate curr = queue.poll();
        Cell currCell = cell[curr.row][curr.col];
        if (currCell != null && currCell instanceof FillableCell) {
          Pipe currPipe = ((FillableCell) currCell).getPipe();
          if (currPipe != null) {
            for (Direction dir : currPipe.getConnections()) {
              int idx = dir.ordinal();
              int nRow = curr.row + dRow[idx];
              int nCol = curr.col + dCol[idx];
              if (nRow >= 1 && nRow < rows - 1 && nCol >= 1 && nCol < cols - 1) {
                Coordinate nCoord = Pa19Factory.eINSTANCE.createCoordinate();
                nCoord.setRow(nRow);
                nCoord.setCol(nCol);
                if (!visited.contains(nCoord)) {
                  Cell nCell = cell[nRow][nCol];
                  if (nCell != null && nCell instanceof FillableCell) {
                    Pipe nPipe = ((FillableCell) nCell).getPipe();
                    if (nPipe != null) {
                      Direction oppDir = Direction.get(dir.getValue() ^ 1);
                      if (nPipe.getConnections().contains(oppDir)) {
                        visited.add(nCoord);
                        filledTiles.add(nCoord);
                        queue.add(nCoord);
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
    prevFilledTiles = filledTiles.size() - recordedCount;
  }

